mapper.select:
SELECT a.usr_id AS user_id, /* 사용자 ID */ a.usr_nm AS user_nm, /* 사용자 명 */ a.ognz_cd, /* 조직 코드 */ b.ognz_nm, /* 소속부서명 */ a.auth_cd AS authrt_cd, /* 권한 코드 */ d.auth_nm AS authrt_nm, /* 권한 코드 - 사용자 등급 */ a.lgn_yn, /* 로그인 여부 */ a.lgn_ip, /* 로그인 IP */ c.cd_nm AS wrk_stat_nm, /* 근태 코드 */ TO_CHAR(a.entr_dt, 'YYYYMMDD') AS jncmp_ymd, /* 입사 일자 */ TO_CHAR(a.rtir_dt, 'YYYYMMDD') AS rsgntn_ymd /* 퇴사 일자 */ FROM cdm_own.usr a /* 사용자 */ LEFT JOIN cdm_own.ognz b /* 조직 */ ON a.ognz_cd = b.ognz_cd LEFT JOIN cdm_own.sup_wrk_stat s /* 근태상태 */ ON s.user_id = a.usr_id AND a.ognz_cd = s.ognz_cd AND s.crtr_ymd = TO_CHAR(CURRENT_DATE, 'YYYYMMDD') LEFT JOIN cdm_own.cmmn_cd c /* 공통코드 */ ON c.cd_grop_cd = 'WRK_STAT_CD' AND c.cmmn_cd = s.wrk_stat_cd AND c.lcal_cd = 'ko' LEFT JOIN cdm_own.auth d /* 권한 */ ON a.auth_cd = d.auth_cd WHERE 1=1
AND a.usr_id LIKE '%' || #{userId} || '%'
AND a.usr_nm LIKE '%' || #{userNm} || '%'
AND a.ognz_cd in ()
AND a.auth_cd = #{authrtCd}
AND a.cti_use_yn = #{ctiUseYn}
AND a.use_yn = #{useYn}
ORDER BY a.usr_id
